/**
 * The release media import (A4 brief §11–§14, §19): registers today's 143 `public/media` files as media items —
 * `storage_area = 'release'`, the address the static site uses as `storage_key`, `legacy_key` = today's MediaId — from the
 * committed baseline (`release-baseline.json`, generated by scripts/media-release-baseline.mjs from the repository).
 * Framework-free; run by `npm run media:import-release`, never by a migration and never at app start.
 *
 * - **Fails closed.** Every file is verified against the baseline (size and SHA-256) and every existing record against
 *   the file, BEFORE anything is written; any difference stops the run with nothing written. The count must be 143.
 * - **Idempotent.** Items are matched by `legacy_key`: a second run finds every item unchanged and writes nothing.
 * - **Never moves or rewrites a file**: the release keeps serving them exactly as before (A9 is the cutover).
 * - **Status:** the 13 held-back files restricted with their documented flags and NO `public_media` row; files the
 *   built site uses approved as a baseline (not a rights claim); unused files pending review. Alt texts only as the
 *   built site gives them consistently (a description, '' for decorative, else undecided). No rights holder, licence or
 *   authorship is invented.
 * - **Refresh** (an explicit, audited workflow): when RAWASY replaces a release file under the same name, regenerate the
 *   baseline and run with `--refresh=<legacy key>`: the record takes the new file's facts, an approved item returns to
 *   review (a changed binary needs approval again), and the change is audited. Release files have no older versions
 *   to keep (the release itself replaced the bytes); A9's move into the persistent store gives them real versions.
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { eq, inArray, isNotNull, sql } from "drizzle-orm";
import type { Pool } from "mysql2/promise";
import { z } from "zod";
import { recordAudit, type AuditActor } from "../audit/audit.ts";
import { inTransaction, type Db } from "../db/client.ts";
import { mediaAssets, mediaFiles, mediaFlags, mediaTranslations } from "../db/schema-media.ts";
import { ulid } from "../security/ids.ts";
import { syncPublicMedia } from "./deliverability.ts";
import { releaseFile } from "./presence.ts";
import { MEDIA_FLAG_KEYS } from "./registry.ts";
import { rebuildMediaSearch } from "./service.ts";

export const RELEASE_COUNT = 143;

const itemSchema = z
  .object({
    legacyKey: z.string().regex(/^[a-z0-9-]+\/[a-z0-9._-]+$/),
    src: z.string().regex(/^\/media\/[a-z0-9-]+\/[a-z0-9._-]+\.webp$/),
    kind: z.literal("image"),
    mime: z.literal("image/webp"),
    width: z.number().int().positive(),
    height: z.number().int().positive(),
    blurDataUrl: z.string().max(600).nullable(),
    byteSize: z.number().int().positive(),
    sha256: z.string().regex(/^[0-9a-f]{64}$/),
    used: z.boolean(),
    alt: z.object({ en: z.string().max(500).nullable(), ar: z.string().max(500).nullable() }).strict(),
    status: z.enum(["approved", "pending_review", "restricted"]),
    flags: z.array(z.enum(MEDIA_FLAG_KEYS as [string, ...string[]])),
    note: z.string().max(2000).nullable(),
  })
  .strict()
  .refine((i) => (i.status === "restricted") === i.flags.length > 0, "a restricted item has its flags, and only a restricted one")
  .refine((i) => i.status !== "approved" || i.used, "only an item the site uses is approved");

export const baselineSchema = z.object({ description: z.string(), count: z.literal(RELEASE_COUNT), items: z.array(itemSchema).length(RELEASE_COUNT) }).strict();

export type BaselineItem = z.infer<typeof itemSchema>;
export type Baseline = z.infer<typeof baselineSchema>;

export function parseBaseline(json: unknown): Baseline {
  const baseline = baselineSchema.parse(json);
  const keys = new Set(baseline.items.map((i) => i.legacyKey));
  if (keys.size !== baseline.items.length) throw new Error("The baseline lists a legacy key twice.");
  const restricted = baseline.items.filter((i) => i.status === "restricted").length;
  if (restricted !== 13) throw new Error(`The baseline holds ${restricted} held-back files, not 13.`);
  return baseline;
}

export interface ImportOptions {
  /** The release's `public/` folder. */
  releaseDir: string;
  /** Who runs it (the audit log's CLI actor). */
  actor: AuditActor;
  requestId: string;
  now: Date;
  dryRun: boolean;
  /** Legacy keys whose changed file may be taken as the new release file (the refresh workflow). */
  refresh: readonly string[];
}

export interface ImportReport {
  created: string[];
  unchanged: string[];
  refreshed: string[];
  /** Why nothing was written (empty when the run could proceed). */
  problems: string[];
}

const APPROVAL_NOTE = "Release baseline (A4 import): used by the approved public website when imported. Not a rights claim.";

async function sha256Of(path: string) {
  return createHash("sha256").update(await readFile(path)).digest("hex");
}

/** Plans and (unless a dry run) applies the import in one transaction; nothing is written when a problem is found. */
export async function importRelease(pool: Pool, db: Db, baseline: Baseline, options: ImportOptions): Promise<ImportReport> {
  const report: ImportReport = { created: [], unchanged: [], refreshed: [], problems: [] };
  // 1. Every release file must be exactly the baseline's.
  for (const item of baseline.items) {
    const path = await releaseFile(options.releaseDir, item.src);
    if (!path) {
      report.problems.push(`${item.legacyKey}: public${item.src} is missing.`);
      continue;
    }
    const hash = await sha256Of(path);
    if (hash !== item.sha256) report.problems.push(`${item.legacyKey}: public${item.src} differs from the baseline (SHA-256). Regenerate the baseline after checking why.`);
  }
  const unknownRefresh = options.refresh.filter((key) => !baseline.items.some((i) => i.legacyKey === key));
  for (const key of unknownRefresh) report.problems.push(`--refresh=${key}: not in the baseline.`);
  if (report.problems.length) return report;
  // 2. Every existing record must still be the file (or be named for a refresh).
  const existing = await db
    .select({ id: mediaAssets.id, legacyKey: mediaAssets.legacyKey, currentFileId: mediaAssets.currentFileId })
    .from(mediaAssets)
    .where(isNotNull(mediaAssets.legacyKey));
  const byKey = new Map(existing.map((e) => [e.legacyKey!, e]));
  for (const key of byKey.keys()) if (!baseline.items.some((i) => i.legacyKey === key)) report.problems.push(`${key}: in the database but not in the baseline (never removed automatically).`);
  const fileIds = existing.map((e) => e.currentFileId).filter((v): v is string => Boolean(v));
  const files = fileIds.length ? await db.select().from(mediaFiles).where(inArray(mediaFiles.id, fileIds)) : [];
  const fileOf = new Map(files.map((f) => [f.id, f]));
  const toRefresh: BaselineItem[] = [];
  const toCreate: BaselineItem[] = [];
  for (const item of baseline.items) {
    const record = byKey.get(item.legacyKey);
    if (!record) {
      toCreate.push(item);
      continue;
    }
    const file = record.currentFileId ? fileOf.get(record.currentFileId) : undefined;
    if (!file || file.storageArea !== "release" || file.storageKey !== item.src) {
      report.problems.push(`${item.legacyKey}: its current file is not the release file ${item.src} (never changed automatically).`);
      continue;
    }
    const same = file.sha256.toString("hex") === item.sha256 && Number(file.byteSize) === item.byteSize && file.width === item.width && file.height === item.height;
    if (same) report.unchanged.push(item.legacyKey);
    else if (options.refresh.includes(item.legacyKey)) toRefresh.push(item);
    else report.problems.push(`${item.legacyKey}: the release file differs from the stored record. Check it, then run with --refresh=${item.legacyKey}.`);
  }
  for (const key of options.refresh) if (!toRefresh.some((i) => i.legacyKey === key)) report.problems.push(`--refresh=${key}: its record is unchanged or missing: nothing to refresh.`);
  if (report.problems.length) return report;
  report.created = toCreate.map((i) => i.legacyKey);
  report.refreshed = toRefresh.map((i) => i.legacyKey);
  if (options.dryRun || (!toCreate.length && !toRefresh.length)) return report;
  // 3. One transaction: every new item, every refresh, their public_media rows, search rows and audit events.
  await inTransaction(pool, async (tx) => {
    for (const item of toCreate) await createReleaseItem(tx, item, options.now);
    for (const item of toRefresh) await refreshReleaseItem(tx, byKey.get(item.legacyKey)!.id, item, options);
    await recordAudit(tx, {
      at: options.now,
      requestId: options.requestId,
      actor: options.actor,
      action: "media.import_release",
      entity: { type: "media", id: null, label: "release media" },
      outcome: "success",
      summary: `Imported the release media: ${toCreate.length} registered, ${toRefresh.length} refreshed, ${report.unchanged.length} unchanged (files never moved).`,
      changes: {
        count: toCreate.length,
        applied: {
          approved: toCreate.filter((i) => i.status === "approved").length,
          pending_review: toCreate.filter((i) => i.status === "pending_review").length,
          restricted: toCreate.filter((i) => i.status === "restricted").length,
        },
      },
    });
  });
  return report;
}

async function createReleaseItem(tx: Db, item: BaselineItem, now: Date) {
  const id = ulid(now.getTime());
  const fileId = ulid(now.getTime());
  const restricted = item.status === "restricted";
  await tx.insert(mediaAssets).values({
    id,
    legacyKey: item.legacyKey,
    kind: "image",
    visibility: "public",
    usageStatus: item.status,
    sourceNote: item.note ?? `Release file public${item.src} (media registry, src/content/media.generated.ts).`,
    ...(item.status === "approved" ? { approvedAt: now, approvedBy: null, approvalNote: APPROVAL_NOTE } : {}),
    ...(restricted ? { restrictedAt: now, restrictedBy: null, restrictionReason: [...(item.note ?? "Held back from the public site.")].slice(0, 500).join("") } : {}),
    lockVersion: 0,
    createdAt: now,
    createdBy: null,
    updatedAt: now,
    updatedBy: null,
  });
  await tx.insert(mediaFiles).values({
    id: fileId,
    mediaId: id,
    version: 1,
    storageArea: "release",
    storageKey: item.src,
    originalFilename: item.src.slice(item.src.lastIndexOf("/") + 1),
    mimeType: item.mime,
    extension: "webp",
    byteSize: item.byteSize,
    sha256: Buffer.from(item.sha256, "hex"),
    width: item.width,
    height: item.height,
    blurDataUrl: item.blurDataUrl,
    processingStatus: "ready",
    uploadedAt: now,
    uploadedBy: null,
  });
  await tx.update(mediaAssets).set({ currentFileId: fileId }).where(eq(mediaAssets.id, id));
  for (const locale of ["en", "ar"] as const) {
    const alt = item.alt[locale];
    if (alt === null) continue;
    await tx.insert(mediaTranslations).values({ mediaId: id, locale, altText: alt, updatedAt: now, updatedBy: null });
  }
  if (item.flags.length) {
    await tx.insert(mediaFlags).values(item.flags.map((flag) => ({ mediaId: id, flag, note: item.note ? [...item.note].slice(0, 500).join("") : null, createdAt: now, createdBy: null })));
  }
  await syncPublicMedia(tx, id, now);
  await rebuildMediaSearch(tx, id, now);
}

async function refreshReleaseItem(tx: Db, id: string, item: BaselineItem, options: ImportOptions) {
  const [asset] = await tx.select().from(mediaAssets).where(eq(mediaAssets.id, id)).for("update");
  if (!asset?.currentFileId) throw new Error("A refreshed item lost its file.");
  const now = options.now;
  await tx
    .update(mediaFiles)
    .set({ sha256: Buffer.from(item.sha256, "hex"), byteSize: item.byteSize, width: item.width, height: item.height, blurDataUrl: item.blurDataUrl })
    .where(eq(mediaFiles.id, asset.currentFileId));
  const backToReview = asset.usageStatus === "approved";
  await tx
    .update(mediaAssets)
    .set({
      ...(backToReview ? { usageStatus: "pending_review" as const, approvedAt: null, approvedBy: null, approvalNote: null } : {}),
      lockVersion: sql`${mediaAssets.lockVersion} + 1`,
      updatedAt: now,
      updatedBy: null,
    })
    .where(eq(mediaAssets.id, id));
  await syncPublicMedia(tx, id, now);
  await recordAudit(tx, {
    at: now,
    requestId: options.requestId,
    actor: options.actor,
    action: "media.release_refresh",
    entity: { type: "media", id, label: item.legacyKey },
    outcome: "success",
    summary: `Refreshed release media ${item.legacyKey} to its new file${backToReview ? "; it returned to review (approval needed again)" : ""}.`,
    changes: { before: { status: asset.usageStatus }, after: { status: backToReview ? "pending_review" : asset.usageStatus } },
  });
}
